<?php

declare(strict_types=1);

use App\Core\Migrations;

return static function (PDO $db, Migrations $schema): void {
	// Antes del DDL se comprueba el contexto histórico; no se reubican registros ni archivos.
	if ($db->query('SELECT a.id FROM auditoria a JOIN procesos_electorales p ON p.id=a.proceso WHERE a.organizacion<>p.organizacion LIMIT 1')->fetchColumn()!==false) throw new RuntimeException('Auditoría histórica con contexto incompatible. Revisar antes de migrar.');
	if ($db->query('SELECT a.id FROM archivos a JOIN usuarios u ON u.id=a.subido_por JOIN usuarios_tipos t ON t.id=u.tipo_usuario WHERE u.organizacion<>a.organizacion AND t.codigo<>\'superadmin\' LIMIT 1')->fetchColumn()!==false) throw new RuntimeException('Archivos históricos con organización incompatible. Revisar antes de migrar.');
	$db->exec('ALTER TABLE auditoria MODIFY organizacion INT NULL');
	foreach (['referencia'=>'VARCHAR(190) NULL','informacion'=>'JSON NULL'] as $column=>$definition) if (!$schema->columnExists('auditoria',$column)) $db->exec("ALTER TABLE auditoria ADD $column $definition");
	if (!$schema->indexExists('auditoria','ix_auditoria_contexto')) $db->exec('ALTER TABLE auditoria ADD INDEX ix_auditoria_contexto (organizacion,proceso,f_registro,id)');
	$db->exec('ALTER TABLE archivos MODIFY tamanio BIGINT NULL');
	foreach (['proceso'=>'INT NULL','sha256'=>'CHAR(64) CHARACTER SET ascii NULL','estado'=>"VARCHAR(16) NOT NULL DEFAULT 'historico'",'ancho'=>'INT NULL','alto'=>'INT NULL'] as $column=>$definition) if (!$schema->columnExists('archivos',$column)) $db->exec("ALTER TABLE archivos ADD $column $definition");
	if (!$schema->indexExists('archivos','ix_archivos_contexto')) $db->exec('ALTER TABLE archivos ADD INDEX ix_archivos_contexto (organizacion,proceso,entidad,entidad_id), ADD CONSTRAINT fk_archivos_proceso FOREIGN KEY (proceso) REFERENCES procesos_electorales(id)');
	$tables = [
		'archivos_variantes'=>"archivo INT NOT NULL, variante VARCHAR(16) NOT NULL, ruta VARCHAR(190) NOT NULL, mime VARCHAR(100) NOT NULL, tamanio BIGINT NOT NULL, sha256 CHAR(64) NOT NULL, ancho INT NULL, alto INT NULL, PRIMARY KEY(archivo,variante), FOREIGN KEY(archivo) REFERENCES archivos(id)",
		'aprobaciones'=>"id INT AUTO_INCREMENT PRIMARY KEY, uuid BINARY(16) NOT NULL UNIQUE, organizacion INT NOT NULL, proceso INT NULL, entidad VARCHAR(80) NOT NULL, entidad_id INT NOT NULL, solicitante INT NOT NULL, estado VARCHAR(16) NOT NULL DEFAULT 'pendiente', regla JSON NOT NULL, informacion JSON NULL, fecha DATETIME NOT NULL, vence_en DATETIME NULL, resuelta_en DATETIME NULL, INDEX(organizacion,proceso,estado,id), FOREIGN KEY(organizacion) REFERENCES organizaciones(id), FOREIGN KEY(proceso) REFERENCES procesos_electorales(id), FOREIGN KEY(solicitante) REFERENCES usuarios(id)",
		'aprobaciones_pasos'=>"aprobacion INT NOT NULL, orden INT NOT NULL, aprobador INT NOT NULL, estado VARCHAR(16) NOT NULL DEFAULT 'pendiente', resuelto_por INT NULL, motivo VARCHAR(500) NULL, fecha DATETIME NULL, PRIMARY KEY(aprobacion,orden), FOREIGN KEY(aprobacion) REFERENCES aprobaciones(id), FOREIGN KEY(aprobador) REFERENCES usuarios(id), FOREIGN KEY(resuelto_por) REFERENCES usuarios(id)",
		'trabajos'=>"id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, tipo VARCHAR(80) NOT NULL, payload JSON NOT NULL, organizacion INT NULL, proceso INT NULL, usuario INT NULL, prioridad SMALLINT NOT NULL DEFAULT 0, estado VARCHAR(16) NOT NULL DEFAULT 'pendiente', intentos INT NOT NULL DEFAULT 0, max_intentos INT NOT NULL DEFAULT 3, disponible_en DATETIME NOT NULL, bloqueo_hasta DATETIME NULL, worker VARCHAR(100) NULL, lease CHAR(36) CHARACTER SET ascii NULL, fecha DATETIME NOT NULL, inicio DATETIME NULL, fin DATETIME NULL, error VARCHAR(500) NULL, idempotencia CHAR(64) CHARACTER SET ascii NULL, UNIQUE KEY uq_trabajo_idempotente(tipo,idempotencia), INDEX ix_trabajo_claim(estado,disponible_en,prioridad,id), FOREIGN KEY(organizacion) REFERENCES organizaciones(id), FOREIGN KEY(proceso) REFERENCES procesos_electorales(id), FOREIGN KEY(usuario) REFERENCES usuarios(id)",
		'notificaciones'=>"id INT AUTO_INCREMENT PRIMARY KEY, uuid BINARY(16) NOT NULL UNIQUE, usuario INT NOT NULL, organizacion INT NULL, proceso INT NULL, tipo VARCHAR(80) NOT NULL, titulo VARCHAR(180) NOT NULL, resumen TEXT NOT NULL, entidad VARCHAR(80) NULL, referencia VARCHAR(190) NULL, enlace VARCHAR(500) NULL, fecha DATETIME NOT NULL, leida_en DATETIME NULL, INDEX(usuario,leida_en,id), FOREIGN KEY(usuario) REFERENCES usuarios(id), FOREIGN KEY(organizacion) REFERENCES organizaciones(id), FOREIGN KEY(proceso) REFERENCES procesos_electorales(id)",
		'notificaciones_config'=>"organizacion INT PRIMARY KEY, email_habilitado TINYINT NOT NULL DEFAULT 0, whatsapp_habilitado TINYINT NOT NULL DEFAULT 0, editado_por INT NOT NULL, fecha DATETIME NOT NULL, FOREIGN KEY(organizacion) REFERENCES organizaciones(id), FOREIGN KEY(editado_por) REFERENCES usuarios(id)",
		'notificaciones_envios'=>"id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, organizacion INT NOT NULL, proceso INT NULL, persona INT NOT NULL, canal VARCHAR(16) NOT NULL, destinatario VARCHAR(150) NOT NULL, plantilla VARCHAR(128) NULL, contenido JSON NOT NULL, estado VARCHAR(16) NOT NULL DEFAULT 'pendiente', intentos INT NOT NULL DEFAULT 0, externo_id VARCHAR(190) NULL, error VARCHAR(500) NULL, fecha DATETIME NOT NULL, enviado_en DATETIME NULL, usuario INT NOT NULL, idempotencia CHAR(64) CHARACTER SET ascii NOT NULL UNIQUE, INDEX(organizacion,proceso,estado,fecha), FOREIGN KEY(organizacion) REFERENCES organizaciones(id), FOREIGN KEY(proceso) REFERENCES procesos_electorales(id), FOREIGN KEY(persona) REFERENCES personas(id), FOREIGN KEY(usuario) REFERENCES usuarios(id)",
		'exportaciones'=>"id INT AUTO_INCREMENT PRIMARY KEY, uuid BINARY(16) NOT NULL UNIQUE, solicitante INT NOT NULL, organizacion INT NOT NULL, proceso INT NULL, tipo VARCHAR(80) NOT NULL, formato VARCHAR(8) NOT NULL, filtros JSON NOT NULL, estado VARCHAR(16) NOT NULL DEFAULT 'pendiente', fecha DATETIME NOT NULL, expira_en DATETIME NOT NULL, archivo INT NULL, error VARCHAR(500) NULL, INDEX(solicitante,organizacion,fecha), FOREIGN KEY(solicitante) REFERENCES usuarios(id), FOREIGN KEY(organizacion) REFERENCES organizaciones(id), FOREIGN KEY(proceso) REFERENCES procesos_electorales(id), FOREIGN KEY(archivo) REFERENCES archivos(id)",
		'respaldos'=>"id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, tipo VARCHAR(16) NOT NULL, estado VARCHAR(16) NOT NULL DEFAULT 'pendiente', base_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, anterior_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, manifiesto JSON NULL, ruta VARCHAR(190) NULL, sha256 CHAR(64) NULL, tamanio BIGINT NULL, cifrado TINYINT NOT NULL DEFAULT 0, protegido TINYINT NOT NULL DEFAULT 0, verificado_en DATETIME NULL, error VARCHAR(500) NULL, usuario INT NOT NULL, fecha DATETIME(6) NOT NULL, inicio DATETIME(6) NULL, fin DATETIME(6) NULL, INDEX(estado,fecha), FOREIGN KEY(base_id) REFERENCES respaldos(id), FOREIGN KEY(anterior_id) REFERENCES respaldos(id), FOREIGN KEY(usuario) REFERENCES usuarios(id)",
		'respaldos_politica'=>"id INT PRIMARY KEY, bd_diaria TINYINT NOT NULL DEFAULT 1, archivos_full_dia SMALLINT NOT NULL DEFAULT 0, archivos_incremental TINYINT NOT NULL DEFAULT 1, retencion_dias INT NOT NULL DEFAULT 14, editado_por INT NULL, fecha DATETIME NOT NULL, FOREIGN KEY(editado_por) REFERENCES usuarios(id)",
		'restauraciones'=>"id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, respaldo CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, usuario INT NOT NULL, estado VARCHAR(16) NOT NULL DEFAULT 'pendiente', destino JSON NOT NULL, previo_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, fecha DATETIME NOT NULL, fin DATETIME NULL, error VARCHAR(500) NULL, FOREIGN KEY(respaldo) REFERENCES respaldos(id), FOREIGN KEY(previo_id) REFERENCES respaldos(id), FOREIGN KEY(usuario) REFERENCES usuarios(id)",
	];
	foreach ($tables as $table=>$columns) $db->exec("CREATE TABLE IF NOT EXISTS $table ($columns) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
	$db->exec('INSERT IGNORE INTO respaldos_politica (id,fecha) VALUES (1,NOW())');
	$permissions = ['auditoria.ver'=>'Consultar auditoría','aprobaciones.ver'=>'Consultar aprobaciones','aprobaciones.resolver'=>'Resolver aprobaciones asignadas','archivos.subir'=>'Subir archivos privados','archivos.ver'=>'Consultar archivos privados','archivos.eliminar'=>'Eliminar archivos propios autorizados','notificaciones.administrar'=>'Configurar notificaciones operativas','exportaciones.generar'=>'Generar exportaciones','exportaciones.descargar'=>'Descargar exportaciones propias','trabajos.ver'=>'Consultar trabajos de la organización','trabajos.administrar'=>'Administrar trabajos propios'];
	$insert = $db->prepare('INSERT IGNORE INTO permisos (id,permiso,descripcion,ambito,f_registro) VALUES (?,?,?,\'ambos\',NOW())');
	$grant = $db->prepare('INSERT INTO permisos_usuarios_tipo (uuid,permiso,tipo,valor,alcance,f_actualizacion) SELECT ?,?,2,1,\'eleccion\',NOW() WHERE NOT EXISTS (SELECT 1 FROM permisos_usuarios_tipo WHERE permiso=? AND tipo=2 AND proceso IS NULL)');
	foreach ($permissions as $code=>$name) { $insert->execute([$code,$name,$name]); $grant->execute([random_bytes(16),$code,$code]); }
};
